  ("id", "userId", "name", "mealType", "calories", "proteinG", "carbsG", "fatG", "prepTimeMin", "ingredientsJson", "stepsJson", "dietTypesJson", "aiGenerated")
VALUES
  (gen_random_uuid()::text, NULL, 'Tapa filipino de patinho com arroz integral e ovo', 'BREAKFAST', 480, 38, 42, 16, 15, '[{"name":"Patinho em bife","amount":"130 g","substitutions":[{"name":"Peito de frango","amount":"120 g"},{"name":"Ovos","amount":"2 unidades"},{"name":"Patinho moido","amount":"120 g"},{"name":"Peito de peru","amount":"100 g"},{"name":"Frango desfiado","amount":"120 g"}]},{"name":"Arroz integral","amount":"100 g cozido","substitutions":[{"name":"Quinoa","amount":"100 g cozida"},{"name":"Batata-doce","amount":"140 g"},{"name":"Mandioca","amount":"120 g"},{"name":"Aveia em flocos","amount":"45 g"},{"name":"Inhame","amount":"140 g"}]},{"name":"Ovos","amount":"1 unidade","substitutions":[{"name":"Peito de frango","amount":"120 g"},{"name":"Patinho moido","amount":"120 g"},{"name":"Peito de peru","amount":"100 g"},{"name":"Frango desfiado","amount":"120 g"},{"name":"Carne de panela magra","amount":"120 g"}]}]'::jsonb, '["Tempere Patinho em bife com alho, limao, ervas e pouco sal.","Grelhe, asse ou cozinhe a proteina e prepare Arroz integral e Ovos em paralelo.","Monte o prato com a porcao cadastrada e evite molhos pesados.","Troque proteina, carboidrato ou vegetal pelas substituicoes cadastradas.","Cozinhe carne moida e preparacoes com ovos ate atingir 71 °C no centro; em ovos simples, firme clara e gema."]'::jsonb, '["OMNIVORE","OTHER"]'::jsonb, false),
  (gen_random_uuid()::text, NULL, 'Tinola filipino de frango com abobrinha e espinafre', 'LUNCH', 470, 42, 28, 18, 30, '[{"name":"Frango desfiado","amount":"150 g","substitutions":[{"name":"Peito de frango","amount":"120 g"},{"name":"Ovos","amount":"2 unidades"},{"name":"Patinho moido","amount":"120 g"},{"name":"Peito de peru","amount":"100 g"},{"name":"Carne de panela magra","amount":"120 g"}]},{"name":"Abobrinha","amount":"120 g","substitutions":[{"name":"Brocolis","amount":"120 g"},{"name":"Cenoura","amount":"100 g"},{"name":"Couve","amount":"100 g"},{"name":"Tomate","amount":"1 unidade"},{"name":"Pimentao","amount":"120 g"}]},{"name":"Espinafre","amount":"80 g","substitutions":[{"name":"Brocolis","amount":"120 g"},{"name":"Abobrinha","amount":"120 g"},{"name":"Cenoura","amount":"100 g"},{"name":"Couve","amount":"100 g"},{"name":"Tomate","amount":"1 unidade"}]},{"name":"Gengibre","amount":"1 colher de cha","substitutions":[{"name":"Limao","amount":"1 unidade"},{"name":"Ervas frescas","amount":"1 colher de sopa"},{"name":"Alho","amount":"1 dente"},{"name":"Vinagre","amount":"1 colher de sopa"},{"name":"Mostarda sem acucar","amount":"1 colher de cha"}]}]'::jsonb, '["Tempere Frango desfiado com alho, limao, ervas e pouco sal.","Grelhe, asse ou cozinhe a proteina e prepare Abobrinha e Espinafre em paralelo.","Monte o prato com a porcao cadastrada e evite molhos pesados.","Troque proteina, carboidrato ou vegetal pelas substituicoes cadastradas.","Cozinhe frango e peru ate atingir 74 °C no centro; refrigere as sobras em ate duas horas."]'::jsonb, '["OMNIVORE","OTHER"]'::jsonb, false),
  (gen_random_uuid()::text, NULL, 'Adobo filipino de frango leve com arroz integral', 'DINNER', 610, 46, 62, 18, 35, '[{"name":"Peito de frango","amount":"170 g","substitutions":[{"name":"Ovos","amount":"2 unidades"},{"name":"Patinho moido","amount":"120 g"},{"name":"Peito de peru","amount":"100 g"},{"name":"Frango desfiado","amount":"120 g"},{"name":"Carne de panela magra","amount":"120 g"}]},{"name":"Arroz integral","amount":"130 g cozido","substitutions":[{"name":"Quinoa","amount":"100 g cozida"},{"name":"Batata-doce","amount":"140 g"},{"name":"Mandioca","amount":"120 g"},{"name":"Aveia em flocos","amount":"45 g"},{"name":"Inhame","amount":"140 g"}]},{"name":"Alho","amount":"1 dente","substitutions":[{"name":"Limao","amount":"1 unidade"},{"name":"Ervas frescas","amount":"1 colher de sopa"},{"name":"Vinagre","amount":"1 colher de sopa"},{"name":"Mostarda sem acucar","amount":"1 colher de cha"},{"name":"Gengibre","amount":"1 colher de cha"}]}]'::jsonb, '["Tempere Peito de frango com alho, limao, ervas e pouco sal.","Grelhe, asse ou cozinhe a proteina e prepare Arroz integral e Alho em paralelo.","Monte o prato com a porcao cadastrada e evite molhos pesados.","Troque proteina, carboidrato ou vegetal pelas substituicoes cadastradas.","Cozinhe frango e peru ate atingir 74 °C no centro; refrigere as sobras em ate duas horas."]'::jsonb, '["OMNIVORE","OTHER"]'::jsonb, false),
  (gen_random_uuid()::text, NULL, 'Sinigang filipino de peixe com berinjela e tomate', 'DINNER', 390, 36, 22, 15, 30, '[{"name":"Pescada branca","amount":"160 g","substitutions":[{"name":"Atum","amount":"120 g"},{"name":"Tilapia","amount":"140 g"},{"name":"Sardinha","amount":"1 lata"},{"name":"Camarao","amount":"140 g"},{"name":"Salmao","amount":"140 g"}]},{"name":"Berinjela","amount":"100 g","substitutions":[{"name":"Brocolis","amount":"120 g"},{"name":"Abobrinha","amount":"120 g"},{"name":"Cenoura","amount":"100 g"},{"name":"Couve","amount":"100 g"},{"name":"Tomate","amount":"1 unidade"}]},{"name":"Tomate","amount":"1 unidade","substitutions":[{"name":"Brocolis","amount":"120 g"},{"name":"Abobrinha","amount":"120 g"},{"name":"Cenoura","amount":"100 g"},{"name":"Couve","amount":"100 g"},{"name":"Pimentao","amount":"120 g"}]}]'::jsonb, '["Tempere Pescada branca com limao, ervas e pouco sal.","Prepare Berinjela e Tomate enquanto a proteina grelha, assa ou aquece rapidamente.","Cozinhe a proteina ate ficar no ponto, sem empanar ou fritar por imersao.","Monte o prato e use substituicoes para variar peixe, base ou vegetal.","Cozinhe peixes e frutos do mar ate 63 °C no centro ou ate a carne ficar opaca e separar facilmente."]'::jsonb, '["PESCATARIAN","OTHER"]'::jsonb, false),
  (gen_random_uuid()::text, NULL, 'Pinakbet filipino de camarao com abobrinha e pimentao', 'LUNCH', 380, 30, 24, 18, 25, '[{"name":"Camarao","amount":"150 g","substitutions":[{"name":"Atum","amount":"120 g"},{"name":"Tilapia","amount":"140 g"},{"name":"Sardinha","amount":"1 lata"},{"name":"Salmao","amount":"140 g"},{"name":"Pescada branca","amount":"150 g"}]},{"name":"Abobrinha","amount":"100 g","substitutions":[{"name":"Brocolis","amount":"120 g"},{"name":"Cenoura","amount":"100 g"},{"name":"Couve","amount":"100 g"},{"name":"Tomate","amount":"1 unidade"},{"name":"Pimentao","amount":"120 g"}]},{"name":"Pimentao","amount":"100 g","substitutions":[{"name":"Brocolis","amount":"120 g"},{"name":"Abobrinha","amount":"120 g"},{"name":"Cenoura","amount":"100 g"},{"name":"Couve","amount":"100 g"},{"name":"Tomate","amount":"1 unidade"}]}]'::jsonb, '["Tempere Camarao com limao, ervas e pouco sal.","Prepare Abobrinha e Pimentao enquanto a proteina grelha, assa ou aquece rapidamente.","Cozinhe a proteina ate ficar no ponto, sem empanar ou fritar por imersao.","Monte o prato e use substituicoes para variar peixe, base ou vegetal.","Cozinhe peixes e frutos do mar ate 63 °C no centro ou ate a carne ficar opaca e separar facilmente."]'::jsonb, '["PESCATARIAN","OTHER"]'::jsonb, false),
  (gen_random_uuid()::text, NULL, 'Ginisang filipino de lentilha com couve', 'LUNCH', 430, 25, 58, 10, 25, '[{"name":"Lentilha","amount":"180 g cozida","substitutions":[{"name":"Feijao","amount":"120 g cozido"},{"name":"Ervilha","amount":"100 g"},{"name":"Grao-de-bico","amount":"120 g cozido"},{"name":"Edamame","amount":"120 g"},{"name":"Feijao branco","amount":"120 g cozido"}]},{"name":"Couve","amount":"100 g","substitutions":[{"name":"Brocolis","amount":"120 g"},{"name":"Abobrinha","amount":"120 g"},{"name":"Cenoura","amount":"100 g"},{"name":"Tomate","amount":"1 unidade"},{"name":"Pimentao","amount":"120 g"}]},{"name":"Alho","amount":"1 dente","substitutions":[{"name":"Limao","amount":"1 unidade"},{"name":"Ervas frescas","amount":"1 colher de sopa"},{"name":"Vinagre","amount":"1 colher de sopa"},{"name":"Mostarda sem acucar","amount":"1 colher de cha"},{"name":"Gengibre","amount":"1 colher de cha"}]}]'::jsonb, '["Separe os ingredientes do ginisang filipino de lentilha com couve e confira as porcoes cadastradas.","Prepare Lentilha, Couve e Alho usando cozimento, grelha ou montagem simples.","Monte o prato na porcao sugerida e ajuste temperos leves no final.","Use uma das substituicoes cadastradas para variar mantendo a mesma estrutura nutricional.","Para marmita, resfrie antes de tampar e mantenha molho, folhas ou crocantes separados ate servir."]'::jsonb, '["VEGAN","VEGETARIAN","OTHER"]'::jsonb, false),
  (gen_random_uuid()::text, NULL, 'Lanche filipino de banana com aveia e castanhas', 'AFTERNOON_SNACK', 340, 11, 48, 12, 10, '[{"name":"Banana","amount":"1 unidade","substitutions":[{"name":"Morango","amount":"120 g"},{"name":"Manga","amount":"120 g"},{"name":"Maca","amount":"1 unidade"},{"name":"Pera","amount":"1 unidade"},{"name":"Mamao","amount":"160 g"}]},{"name":"Aveia em flocos","amount":"40 g","substitutions":[{"name":"Arroz integral","amount":"100 g cozido"},{"name":"Quinoa","amount":"100 g cozida"},{"name":"Batata-doce","amount":"140 g"},{"name":"Mandioca","amount":"120 g"},{"name":"Inhame","amount":"140 g"}]},{"name":"Castanhas","amount":"20 g","substitutions":[{"name":"Abacate","amount":"80 g"},{"name":"Azeite de oliva","amount":"1 colher de sopa"},{"name":"Pasta de amendoim","amount":"1 colher de sopa"},{"name":"Nozes","amount":"20 g"},{"name":"Tahine","amount":"1 colher de sopa"}]}]'::jsonb, '["Separe os ingredientes do lanche filipino de banana com aveia e castanhas e confira as porcoes cadastradas.","Prepare Banana, Aveia em flocos e Castanhas usando cozimento, grelha ou montagem simples.","Monte o prato na porcao sugerida e ajuste temperos leves no final.","Use uma das substituicoes cadastradas para variar mantendo a mesma estrutura nutricional.","Leve em pote fechado e mantenha refrigerado quando houver laticinios, ovos, peixe ou frango."]'::jsonb, '["VEGAN","VEGETARIAN","OTHER"]'::jsonb, false),
  (gen_random_uuid()::text, NULL, 'Caldo filipino de peixe com arroz integral e gengibre', 'SUPPER', 370, 29, 34, 12, 25, '[{"name":"Tilapia","amount":"140 g","substitutions":[{"name":"Atum","amount":"120 g"},{"name":"Sardinha","amount":"1 lata"},{"name":"Camarao","amount":"140 g"},{"name":"Salmao","amount":"140 g"},{"name":"Pescada branca","amount":"150 g"}]},{"name":"Arroz integral","amount":"80 g cozido","substitutions":[{"name":"Quinoa","amount":"100 g cozida"},{"name":"Batata-doce","amount":"140 g"},{"name":"Mandioca","amount":"120 g"},{"name":"Aveia em flocos","amount":"45 g"},{"name":"Inhame","amount":"140 g"}]},{"name":"Gengibre","amount":"1 colher de cha","substitutions":[{"name":"Limao","amount":"1 unidade"},{"name":"Ervas frescas","amount":"1 colher de sopa"},{"name":"Alho","amount":"1 dente"},{"name":"Vinagre","amount":"1 colher de sopa"},{"name":"Mostarda sem acucar","amount":"1 colher de cha"}]}]'::jsonb, '["Tempere Tilapia com limao, ervas e pouco sal.","Prepare Arroz integral e Gengibre enquanto a proteina grelha, assa ou aquece rapidamente.","Cozinhe a proteina ate ficar no ponto, sem empanar ou fritar por imersao.","Monte o prato e use substituicoes para variar peixe, base ou vegetal.","Cozinhe peixes e frutos do mar ate 63 °C no centro ou ate a carne ficar opaca e separar facilmente."]'::jsonb, '["PESCATARIAN","OTHER"]'::jsonb, false);
